inventory.expression:
{
      toggleLink: {
        keys: [[Key.Mod, "k"]],
        preventDefault: true,
        handler: ({ editor }) => {
          editor.getApi(linkPlugin).a.show();
        },
      },
    }

calls:
editor.tf.select(
      editor.api.node({
        at: [],
        mode: "lowest",
        match: (n) => n.type === linkPlugin.key && n.id === activeLinkId,
      })![0],
    )

editor.tf.setNodes(
        { icon: document.icon, title: document.title },
        {
          at: [],
          mode: "lowest",
          match: (n) => n.type === linkPlugin.key && n.id === element.id,
        },
      )

editor.tf.withoutNormalizing(() => {
                    tf.insert.tableRow({ at: editor.api.findPath(element) });
                    tf.insert.tableColumn({
                      at: editor.api.findPath(element),
                    });
                  })

useElementSelector(([node]) => node.id as string, [], {
    key: KEYS.tr,
  })
